import numpy as np

def normalise(P):
    """P / P[0]: every column starts at 1."""
    P = np.asarray(P, dtype=float)
    return P / P[0]


def ssd(a, b):
    """Sum of squared differences of two equal-length paths, as a float."""
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return float(np.sum((a - b) ** 2))
